WITH d(name_en, name_mr, desc_en, desc_mr, elig_en, elig_mr, docs_en, docs_mr, ben_en, ben_mr, cat_en, cat_mr, url, helpline, ord) AS (
VALUES
('PM Kisan Samman Nidhi','पीएम किसान सन्मान निधी','Income support of Rs 6,000 per year for small and marginal farmer families.','अल्प व अत्यल्प भूधारक शेतकरी कुटुंबांना वार्षिक रु. ६,००० उत्पन्न सहाय्य.','Land-holding farmer families; institutional landholders and taxpayers are excluded.','जमीनधारक शेतकरी कुटुंब; संस्थात्मक जमीनधारक व आयकरदाते वगळून.','Aadhaar, land records (7/12), bank passbook, mobile number.','आधार, सातबारा उतारा, बँक पासबुक, मोबाईल नंबर.','Rs 6,000 per year in three equal instalments directly in the bank account.','दरवर्षी रु. ६,००० तीन समान हप्त्यांमध्ये थेट बँक खात्यात.','Farmer','शेतकरी','https://pmkisan.gov.in','155261',1),
('Ladki Bahin Yojana','लाडकी बहीण योजना','Monthly financial assistance for eligible women of Maharashtra.','महाराष्ट्रातील पात्र महिलांना दरमहा आर्थिक सहाय्य.','Women aged 21-65 years, resident of Maharashtra, family income below Rs 2.5 lakh.','२१ ते ६५ वयोगटातील महाराष्ट्रातील महिला, कौटुंबिक उत्पन्न रु. २.५ लाखांपेक्षा कमी.','Aadhaar, domicile certificate, ration card, income certificate, bank passbook.','आधार, अधिवास प्रमाणपत्र, रेशनकार्ड, उत्पन्न प्रमाणपत्र, बँक पासबुक.','Monthly assistance credited directly to the woman''s bank account.','दरमहा सहाय्य थेट महिलेच्या बँक खात्यात.','Women','महिला','https://ladakibahin.maharashtra.gov.in','181',2),
('Ayushman Bharat','आयुष्मान भारत','Health cover of Rs 5 lakh per family per year for secondary and tertiary care.','प्रति कुटुंब प्रति वर्ष रु. ५ लाखांपर्यंत मोफत आरोग्य उपचार.','Families listed in SECC deprivation criteria or with a valid Ayushman card.','SECC यादीतील कुटुंबे किंवा वैध आयुष्मान कार्डधारक.','Aadhaar, ration card, Ayushman card, mobile number.','आधार, रेशनकार्ड, आयुष्मान कार्ड, मोबाईल नंबर.','Cashless treatment up to Rs 5 lakh at empanelled hospitals.','सूचीबद्ध रुग्णालयांत रु. ५ लाखांपर्यंत कॅशलेस उपचार.','Health','आरोग्य','https://beneficiary.nha.gov.in','14555',3),
('PM Awas Yojana','पंतप्रधान आवास योजना','Financial assistance to build or buy a pucca house.','पक्के घर बांधण्यासाठी किंवा खरेदीसाठी आर्थिक सहाय्य.','Families without a pucca house; EWS, LIG and MIG income groups.','पक्के घर नसलेली कुटुंबे; EWS, LIG व MIG उत्पन्न गट.','Aadhaar, income certificate, bank passbook, property papers.','आधार, उत्पन्न प्रमाणपत्र, बँक पासबुक, मालमत्ता कागदपत्रे.','Subsidy on home loan interest and construction assistance.','गृहकर्ज व्याज अनुदान व बांधकाम सहाय्य.','Housing','घरकुल','https://pmaymis.gov.in','1800-11-6446',4),
('MahaDBT Scholarship','महाडीबीटी शिष्यवृत्ती','Single portal for all Maharashtra government scholarships for students.','विद्यार्थ्यांसाठी महाराष्ट्र शासनाच्या सर्व शिष्यवृत्तींचे एकत्रित पोर्टल.','Students of Maharashtra studying in recognised institutions, as per scheme income limits.','मान्यताप्राप्त संस्थेत शिकणारे महाराष्ट्रातील विद्यार्थी, योजनेच्या उत्पन्न मर्यादेनुसार.','Aadhaar, caste certificate, income certificate, marksheets, bank passbook.','आधार, जात प्रमाणपत्र, उत्पन्न प्रमाणपत्र, गुणपत्रिका, बँक पासबुक.','Tuition fee, exam fee and maintenance allowance in the bank account.','शिक्षण शुल्क, परीक्षा शुल्क व निर्वाह भत्ता बँक खात्यात.','Education','शिक्षण','https://mahadbt.maharashtra.gov.in','022-49150800',5),
('Income Certificate','उत्पन्न प्रमाणपत्र','Official certificate of annual family income issued by the revenue department.','महसूल विभागाकडून दिले जाणारे कौटुंबिक वार्षिक उत्पन्नाचे अधिकृत प्रमाणपत्र.','Any resident of Maharashtra needing proof of family income.','उत्पन्नाचा पुरावा आवश्यक असलेला महाराष्ट्रातील कोणताही रहिवासी.','Aadhaar, ration card, self-declaration, salary slip or Talathi report.','आधार, रेशनकार्ड, स्वयंघोषणापत्र, पगारपत्रक किंवा तलाठी अहवाल.','Required for scholarships, reservations and welfare schemes.','शिष्यवृत्ती, आरक्षण व कल्याणकारी योजनांसाठी आवश्यक.','Certificate','प्रमाणपत्र','https://aaplesarkar.mahaonline.gov.in','1800-120-8040',6),
('PM Ujjwala Yojana','पीएम उज्ज्वला योजना','Free LPG gas connection for women from below poverty line households.','दारिद्र्यरेषेखालील कुटुंबातील महिलांना मोफत गॅस जोडणी.','Adult woman from a BPL or eligible household without an existing LPG connection.','गॅस जोडणी नसलेल्या BPL किंवा पात्र कुटुंबातील प्रौढ महिला.','Aadhaar, ration card, bank passbook, address proof.','आधार, रेशनकार्ड, बँक पासबुक, रहिवासी पुरावा.','Free connection with deposit-free cylinder and stove support.','अनामत रकमेशिवाय जोडणी, सिलिंडर व शेगडी सहाय्य.','Women','महिला','https://www.pmuy.gov.in','1800-266-6696',7),
('PM Vishwakarma','पीएम विश्वकर्मा','Support for traditional artisans and craftspeople with training, toolkit and credit.','पारंपरिक कारागिरांना प्रशिक्षण, अवजार संच व कर्ज सहाय्य.','Artisans in 18 notified trades, aged 18 or above, self-employed.','१८ अधिसूचित व्यवसायांतील १८ वर्षांवरील स्वयंरोजगार कारागीर.','Aadhaar, mobile number, bank passbook, ration card.','आधार, मोबाईल नंबर, बँक पासबुक, रेशनकार्ड.','Toolkit incentive, skill training stipend and collateral-free loan at low interest.','अवजार अनुदान, प्रशिक्षण विद्यावेतन व विनातारण अल्पव्याज कर्ज.','Livelihood','रोजगार','https://pmvishwakarma.gov.in','18002677777',8),
('Atal Pension Yojana','अटल पेन्शन योजना','Guaranteed pension after the age of 60 for workers in the unorganised sector.','असंघटित क्षेत्रातील कामगारांना वयाच्या ६० नंतर हमी पेन्शन.','Indian citizens aged 18-40 with a savings bank account.','बचत बँक खाते असलेले १८ ते ४० वयोगटातील भारतीय नागरिक.','Aadhaar, bank account, mobile number.','आधार, बँक खाते, मोबाईल नंबर.','Monthly pension of Rs 1,000 to Rs 5,000 after age 60.','वयाच्या ६० नंतर दरमहा रु. १,००० ते रु. ५,००० पेन्शन.','Pension','पेन्शन','https://www.npscra.nsdl.co.in/scheme-details.php#APY','1800-110-069',9),
('Sukanya Samriddhi Yojana','सुकन्या समृद्धी योजना','Small savings scheme for the education and marriage of a girl child.','मुलीच्या शिक्षण व विवाहासाठी अल्पबचत योजना.','Parents or guardians of a girl child below 10 years of age.','१० वर्षांखालील मुलीचे पालक किंवा पालनकर्ते.','Girl''s birth certificate, Aadhaar of guardian, address proof, photo.','मुलीचा जन्म दाखला, पालकाचे आधार, रहिवासी पुरावा, फोटो.','High interest rate with tax benefit and maturity amount for the girl.','उच्च व्याजदर, करसवलत व मुदतपूर्तीची रक्कम मुलीला.','Girl Child','मुलगी','https://www.indiapost.gov.in','1800-266-6868',10),
('PM Mudra Yojana','पीएम मुद्रा योजना','Collateral-free business loans up to Rs 10 lakh for micro enterprises.','सूक्ष्म उद्योगांसाठी रु. १० लाखांपर्यंत विनातारण व्यवसाय कर्ज.','Non-farm micro and small business owners and new entrepreneurs.','बिगरशेती सूक्ष्म व लघु व्यावसायिक तसेच नवउद्योजक.','Aadhaar, PAN, business plan, bank statements, address proof.','आधार, पॅन, व्यवसाय आराखडा, बँक स्टेटमेंट, रहिवासी पुरावा.','Shishu, Kishor and Tarun loans without collateral.','शिशु, किशोर व तरुण गटातील विनातारण कर्ज.','Business','व्यवसाय','https://www.mudra.org.in','1800-180-1111',11),
('PM Surya Ghar Muft Bijli','पीएम सूर्य घर मोफत वीज','Rooftop solar subsidy giving households free electricity every month.','छतावरील सौर प्रकल्प अनुदानातून कुटुंबांना दरमहा मोफत वीज.','Households owning a roof with a valid electricity connection.','वैध वीज जोडणी असलेली स्वतःचे छत असणारी कुटुंबे.','Aadhaar, electricity bill, property proof, bank passbook.','आधार, वीज बिल, मालमत्ता पुरावा, बँक पासबुक.','Central subsidy on rooftop solar and up to 300 units free power.','सौर प्रकल्पावर केंद्र अनुदान व ३०० युनिटपर्यंत मोफत वीज.','Energy','ऊर्जा','https://pmsuryaghar.gov.in','1800-11-4455',12),
('eShram Card','ई-श्रम कार्ड','National database registration card for unorganised sector workers.','असंघटित क्षेत्रातील कामगारांसाठी राष्ट्रीय नोंदणी कार्ड.','Workers aged 16-59 in the unorganised sector, not an EPFO or ESIC member.','१६ ते ५९ वयोगटातील असंघटित कामगार, EPFO किंवा ESIC सदस्य नसावा.','Aadhaar linked mobile number, bank account details.','आधारशी जोडलेला मोबाईल क्रमांक, बँक खाते तपशील.','Accident insurance cover and access to worker welfare schemes.','अपघात विमा संरक्षण व कामगार कल्याण योजनांचा लाभ.','Worker','कामगार','https://eshram.gov.in','14434',13),
('MJPJAY','महात्मा ज्योतिराव फुले जन आरोग्य योजना','Maharashtra health scheme for cashless treatment of serious illnesses.','गंभीर आजारांवर मोफत उपचारासाठी महाराष्ट्र शासनाची आरोग्य योजना.','Ration card holding families of Maharashtra as notified under the scheme.','योजनेत नमूद केलेली महाराष्ट्रातील रेशनकार्डधारक कुटुंबे.','Ration card, Aadhaar, doctor''s referral, health card.','रेशनकार्ड, आधार, डॉक्टरांचा संदर्भ, आरोग्य कार्ड.','Cashless surgeries and treatment at empanelled hospitals.','सूचीबद्ध रुग्णालयांत मोफत शस्त्रक्रिया व उपचार.','Health','आरोग्य','https://www.jeevandayee.gov.in','155388',14),
('Mukhyamantri Vayoshri Yojana','मुख्यमंत्री वयोश्री योजना','Assistance to senior citizens for assistive devices and care.','ज्येष्ठ नागरिकांना सहाय्यक साधने व काळजीसाठी अर्थसहाय्य.','Maharashtra residents aged 65 and above with family income below Rs 2 lakh.','६५ वर्षांवरील महाराष्ट्रातील नागरिक, कौटुंबिक उत्पन्न रु. २ लाखांपेक्षा कमी.','Aadhaar, age proof, income certificate, bank passbook.','आधार, वयाचा पुरावा, उत्पन्न प्रमाणपत्र, बँक पासबुक.','Financial assistance for hearing aids, spectacles, walking aids and therapy.','श्रवणयंत्र, चष्मा, चालण्याची साधने व उपचारासाठी अर्थसहाय्य.','Senior Citizen','ज्येष्ठ नागरिक','https://sjsa.maharashtra.gov.in','1800-120-8040',15),
('Old Age Pension','वृद्धापकाळ निवृत्तीवेतन','Monthly pension for destitute senior citizens under the national scheme.','निराधार ज्येष्ठ नागरिकांसाठी राष्ट्रीय योजनेतून दरमहा निवृत्तीवेतन.','Senior citizens aged 60 and above from below poverty line families.','दारिद्र्यरेषेखालील ६० वर्षांवरील ज्येष्ठ नागरिक.','Aadhaar, age proof, BPL ration card, bank passbook.','आधार, वयाचा पुरावा, BPL रेशनकार्ड, बँक पासबुक.','Monthly pension credited to the bank account.','दरमहा निवृत्तीवेतन बँक खात्यात जमा.','Pension','पेन्शन','https://nsap.nic.in','1800-111-555',16),
('Caste Certificate','जात प्रमाणपत्र','Official proof of caste issued by the revenue department.','महसूल विभागाकडून दिले जाणारे अधिकृत जात प्रमाणपत्र.','Residents of Maharashtra belonging to a notified caste category.','अधिसूचित जात प्रवर्गातील महाराष्ट्रातील रहिवासी.','Aadhaar, school leaving certificate, father''s caste proof, ration card.','आधार, शाळा सोडल्याचा दाखला, वडिलांचा जातीचा पुरावा, रेशनकार्ड.','Required for reservation in education, jobs and welfare schemes.','शिक्षण, नोकरी व योजनांतील आरक्षणासाठी आवश्यक.','Certificate','प्रमाणपत्र','https://aaplesarkar.mahaonline.gov.in','1800-120-8040',17),
('Residence Certificate','रहिवासी प्रमाणपत्र','Certificate confirming your place of residence.','आपल्या राहत्या ठिकाणाची पुष्टी करणारे प्रमाणपत्र.','Any person residing at the given address in Maharashtra.','महाराष्ट्रातील दिलेल्या पत्त्यावर राहणारी कोणतीही व्यक्ती.','Aadhaar, ration card, electricity bill, self-declaration.','आधार, रेशनकार्ड, वीज बिल, स्वयंघोषणापत्र.','Used as address proof for admissions, jobs and government services.','प्रवेश, नोकरी व शासकीय सेवांसाठी पत्त्याचा पुरावा.','Certificate','प्रमाणपत्र','https://aaplesarkar.mahaonline.gov.in','1800-120-8040',18),
('Domicile Certificate','अधिवास प्रमाणपत्र','Certificate proving that you are a permanent resident of Maharashtra.','आपण महाराष्ट्राचे कायम रहिवासी असल्याचे सिद्ध करणारे प्रमाणपत्र.','Persons residing in Maharashtra for the period prescribed by the rules.','नियमानुसार विहित कालावधीपासून महाराष्ट्रात राहणाऱ्या व्यक्ती.','Aadhaar, school leaving certificate, ration card, residence proof.','आधार, शाळा सोडल्याचा दाखला, रेशनकार्ड, रहिवासी पुरावा.','Required for state quota admissions and state government jobs.','राज्य कोट्यातील प्रवेश व राज्य शासकीय नोकऱ्यांसाठी आवश्यक.','Certificate','प्रमाणपत्र','https://aaplesarkar.mahaonline.gov.in','1800-120-8040',19),
('Birth Certificate','जन्म दाखला','Official registration certificate of birth.','जन्माची अधिकृत नोंदणी करणारे प्रमाणपत्र.','Parents or guardians registering a birth, or citizens needing a copy.','जन्म नोंदणी करणारे पालक किंवा प्रत हवी असलेले नागरिक.','Hospital birth record, parents'' Aadhaar, address proof.','रुग्णालयाची जन्म नोंद, पालकांचे आधार, रहिवासी पुरावा.','Legal proof of date of birth for school, passport and all documents.','शाळा, पासपोर्ट व सर्व कागदपत्रांसाठी जन्मतारखेचा कायदेशीर पुरावा.','Certificate','प्रमाणपत्र','https://crsorgi.gov.in','1800-120-8040',20),
('Death Certificate','मृत्यू दाखला','Official registration certificate of death.','मृत्यूची अधिकृत नोंदणी करणारे प्रमाणपत्र.','Family members of the deceased person.','मृत व्यक्तीचे कुटुंबीय.','Hospital death record, Aadhaar of deceased, applicant''s ID proof.','रुग्णालयाची मृत्यू नोंद, मृताचे आधार, अर्जदाराचा ओळखपत्र पुरावा.','Needed for insurance claims, pension and property transfer.','विमा दावा, पेन्शन व मालमत्ता हस्तांतरणासाठी आवश्यक.','Certificate','प्रमाणपत्र','https://crsorgi.gov.in','1800-120-8040',21),
('Marriage Registration','विवाह नोंदणी','Legal registration of marriage with the local body.','स्थानिक स्वराज्य संस्थेकडे विवाहाची कायदेशीर नोंदणी.','Married couples residing in Maharashtra with valid marriage proof.','वैध विवाह पुरावा असलेली महाराष्ट्रातील विवाहित जोडपी.','Aadhaar of both spouses, marriage invitation or photos, witnesses'' ID.','दोघांचे आधार, विवाह पत्रिका किंवा फोटो, साक्षीदारांचे ओळखपत्र.','Legal marriage certificate for visa, bank and insurance purposes.','व्हिसा, बँक व विमा कामांसाठी कायदेशीर विवाह प्रमाणपत्र.','Certificate','प्रमाणपत्र','https://aaplesarkar.mahaonline.gov.in','1800-120-8040',22),
('PAN Card','पॅन कार्ड','Permanent Account Number card issued by the Income Tax Department.','आयकर विभागाकडून दिले जाणारे कायम खाते क्रमांक कार्ड.','Any Indian citizen or entity requiring a PAN for financial transactions.','आर्थिक व्यवहारांसाठी पॅन आवश्यक असलेला कोणताही भारतीय नागरिक.','Aadhaar, date of birth proof, address proof, photograph.','आधार, जन्मतारखेचा पुरावा, रहिवासी पुरावा, छायाचित्र.','Mandatory for bank accounts, income tax returns and large transactions.','बँक खाते, आयकर विवरण व मोठ्या व्यवहारांसाठी आवश्यक.','Document','कागदपत्र','https://www.onlineservices.nsdl.com','020-27218080',23),
('Passport','पासपोर्ट','Indian passport application and renewal through Passport Seva.','पासपोर्ट सेवा मार्फत भारतीय पासपोर्ट अर्ज व नूतनीकरण.','Indian citizens with valid identity and address proof.','वैध ओळख व रहिवासी पुरावा असलेले भारतीय नागरिक.','Aadhaar, birth certificate, address proof, old passport if any.','आधार, जन्म दाखला, रहिवासी पुरावा, जुना पासपोर्ट असल्यास.','Internationally accepted travel and identity document.','आंतरराष्ट्रीय प्रवास व ओळखीसाठी मान्य दस्तऐवज.','Document','कागदपत्र','https://www.passportindia.gov.in','1800-258-1800',24)
)
UPDATE public.schemes s SET
  name_mr = CASE WHEN coalesce(s.name_mr,'') = '' THEN d.name_mr ELSE s.name_mr END,
  desc_en = CASE WHEN coalesce(s.desc_en,'') = '' THEN d.desc_en ELSE s.desc_en END,
  desc_mr = CASE WHEN coalesce(s.desc_mr,'') = '' THEN d.desc_mr ELSE s.desc_mr END,
  eligibility_en = CASE WHEN coalesce(s.eligibility_en,'') = '' THEN d.elig_en ELSE s.eligibility_en END,
  eligibility_mr = CASE WHEN coalesce(s.eligibility_mr,'') = '' THEN d.elig_mr ELSE s.eligibility_mr END,
  documents_en = CASE WHEN coalesce(s.documents_en,'') = '' THEN d.docs_en ELSE s.documents_en END,
  documents_mr = CASE WHEN coalesce(s.documents_mr,'') = '' THEN d.docs_mr ELSE s.documents_mr END,
  benefits_en = CASE WHEN coalesce(s.benefits_en,'') = '' THEN d.ben_en ELSE s.benefits_en END,
  benefits_mr = CASE WHEN coalesce(s.benefits_mr,'') = '' THEN d.ben_mr ELSE s.benefits_mr END,
  category_en = CASE WHEN coalesce(s.category_en,'') = '' THEN d.cat_en ELSE s.category_en END,
  category_mr = CASE WHEN coalesce(s.category_mr,'') = '' THEN d.cat_mr ELSE s.category_mr END,
  website_url = CASE WHEN coalesce(s.website_url,'') = '' THEN d.url ELSE s.website_url END,
  helpline = CASE WHEN coalesce(s.helpline,'') = '' THEN d.helpline ELSE s.helpline END,
  updated_at = now()
FROM d
WHERE lower(s.name_en) = lower(d.name_en) OR lower(d.name_en) LIKE lower(s.name_en) || '%';

WITH d(name_en, name_mr, desc_en, desc_mr, elig_en, elig_mr, docs_en, docs_mr, ben_en, ben_mr, cat_en, cat_mr, url, helpline, ord) AS (
VALUES
('PM Vishwakarma','पीएम विश्वकर्मा','Support for traditional artisans and craftspeople with training, toolkit and credit.','पारंपरिक कारागिरांना प्रशिक्षण, अवजार संच व कर्ज सहाय्य.','Artisans in 18 notified trades, aged 18 or above, self-employed.','१८ अधिसूचित व्यवसायांतील १८ वर्षांवरील स्वयंरोजगार कारागीर.','Aadhaar, mobile number, bank passbook, ration card.','आधार, मोबाईल नंबर, बँक पासबुक, रेशनकार्ड.','Toolkit incentive, skill training stipend and collateral-free loan at low interest.','अवजार अनुदान, प्रशिक्षण विद्यावेतन व विनातारण अल्पव्याज कर्ज.','Livelihood','रोजगार','https://pmvishwakarma.gov.in','18002677777',8),
('Atal Pension Yojana','अटल पेन्शन योजना','Guaranteed pension after the age of 60 for workers in the unorganised sector.','असंघटित क्षेत्रातील कामगारांना वयाच्या ६० नंतर हमी पेन्शन.','Indian citizens aged 18-40 with a savings bank account.','बचत बँक खाते असलेले १८ ते ४० वयोगटातील भारतीय नागरिक.','Aadhaar, bank account, mobile number.','आधार, बँक खाते, मोबाईल नंबर.','Monthly pension of Rs 1,000 to Rs 5,000 after age 60.','वयाच्या ६० नंतर दरमहा रु. १,००० ते रु. ५,००० पेन्शन.','Pension','पेन्शन','https://www.npscra.nsdl.co.in/scheme-details.php#APY','1800-110-069',9),
('Sukanya Samriddhi Yojana','सुकन्या समृद्धी योजना','Small savings scheme for the education and marriage of a girl child.','मुलीच्या शिक्षण व विवाहासाठी अल्पबचत योजना.','Parents or guardians of a girl child below 10 years of age.','१० वर्षांखालील मुलीचे पालक किंवा पालनकर्ते.','Girl''s birth certificate, Aadhaar of guardian, address proof, photo.','मुलीचा जन्म दाखला, पालकाचे आधार, रहिवासी पुरावा, फोटो.','High interest rate with tax benefit and maturity amount for the girl.','उच्च व्याजदर, करसवलत व मुदतपूर्तीची रक्कम मुलीला.','Girl Child','मुलगी','https://www.indiapost.gov.in','1800-266-6868',10),
('PM Mudra Yojana','पीएम मुद्रा योजना','Collateral-free business loans up to Rs 10 lakh for micro enterprises.','सूक्ष्म उद्योगांसाठी रु. १० लाखांपर्यंत विनातारण व्यवसाय कर्ज.','Non-farm micro and small business owners and new entrepreneurs.','बिगरशेती सूक्ष्म व लघु व्यावसायिक तसेच नवउद्योजक.','Aadhaar, PAN, business plan, bank statements, address proof.','आधार, पॅन, व्यवसाय आराखडा, बँक स्टेटमेंट, रहिवासी पुरावा.','Shishu, Kishor and Tarun loans without collateral.','शिशु, किशोर व तरुण गटातील विनातारण कर्ज.','Business','व्यवसाय','https://www.mudra.org.in','1800-180-1111',11),
('PM Surya Ghar Muft Bijli','पीएम सूर्य घर मोफत वीज','Rooftop solar subsidy giving households free electricity every month.','छतावरील सौर प्रकल्प अनुदानातून कुटुंबांना दरमहा मोफत वीज.','Households owning a roof with a valid electricity connection.','वैध वीज जोडणी असलेली स्वतःचे छत असणारी कुटुंबे.','Aadhaar, electricity bill, property proof, bank passbook.','आधार, वीज बिल, मालमत्ता पुरावा, बँक पासबुक.','Central subsidy on rooftop solar and up to 300 units free power.','सौर प्रकल्पावर केंद्र अनुदान व ३०० युनिटपर्यंत मोफत वीज.','Energy','ऊर्जा','https://pmsuryaghar.gov.in','1800-11-4455',12),
('eShram Card','ई-श्रम कार्ड','National database registration card for unorganised sector workers.','असंघटित क्षेत्रातील कामगारांसाठी राष्ट्रीय नोंदणी कार्ड.','Workers aged 16-59 in the unorganised sector, not an EPFO or ESIC member.','१६ ते ५९ वयोगटातील असंघटित कामगार, EPFO किंवा ESIC सदस्य नसावा.','Aadhaar linked mobile number, bank account details.','आधारशी जोडलेला मोबाईल क्रमांक, बँक खाते तपशील.','Accident insurance cover and access to worker welfare schemes.','अपघात विमा संरक्षण व कामगार कल्याण योजनांचा लाभ.','Worker','कामगार','https://eshram.gov.in','14434',13),
('MJPJAY','महात्मा ज्योतिराव फुले जन आरोग्य योजना','Maharashtra health scheme for cashless treatment of serious illnesses.','गंभीर आजारांवर मोफत उपचारासाठी महाराष्ट्र शासनाची आरोग्य योजना.','Ration card holding families of Maharashtra as notified under the scheme.','योजनेत नमूद केलेली महाराष्ट्रातील रेशनकार्डधारक कुटुंबे.','Ration card, Aadhaar, doctor''s referral, health card.','रेशनकार्ड, आधार, डॉक्टरांचा संदर्भ, आरोग्य कार्ड.','Cashless surgeries and treatment at empanelled hospitals.','सूचीबद्ध रुग्णालयांत मोफत शस्त्रक्रिया व उपचार.','Health','आरोग्य','https://www.jeevandayee.gov.in','155388',14),
('Mukhyamantri Vayoshri Yojana','मुख्यमंत्री वयोश्री योजना','Assistance to senior citizens for assistive devices and care.','ज्येष्ठ नागरिकांना सहाय्यक साधने व काळजीसाठी अर्थसहाय्य.','Maharashtra residents aged 65 and above with family income below Rs 2 lakh.','६५ वर्षांवरील महाराष्ट्रातील नागरिक, कौटुंबिक उत्पन्न रु. २ लाखांपेक्षा कमी.','Aadhaar, age proof, income certificate, bank passbook.','आधार, वयाचा पुरावा, उत्पन्न प्रमाणपत्र, बँक पासबुक.','Financial assistance for hearing aids, spectacles, walking aids and therapy.','श्रवणयंत्र, चष्मा, चालण्याची साधने व उपचारासाठी अर्थसहाय्य.','Senior Citizen','ज्येष्ठ नागरिक','https://sjsa.maharashtra.gov.in','1800-120-8040',15),
('Old Age Pension','वृद्धापकाळ निवृत्तीवेतन','Monthly pension for destitute senior citizens under the national scheme.','निराधार ज्येष्ठ नागरिकांसाठी राष्ट्रीय योजनेतून दरमहा निवृत्तीवेतन.','Senior citizens aged 60 and above from below poverty line families.','दारिद्र्यरेषेखालील ६० वर्षांवरील ज्येष्ठ नागरिक.','Aadhaar, age proof, BPL ration card, bank passbook.','आधार, वयाचा पुरावा, BPL रेशनकार्ड, बँक पासबुक.','Monthly pension credited to the bank account.','दरमहा निवृत्तीवेतन बँक खात्यात जमा.','Pension','पेन्शन','https://nsap.nic.in','1800-111-555',16),
('Caste Certificate','जात प्रमाणपत्र','Official proof of caste issued by the revenue department.','महसूल विभागाकडून दिले जाणारे अधिकृत जात प्रमाणपत्र.','Residents of Maharashtra belonging to a notified caste category.','अधिसूचित जात प्रवर्गातील महाराष्ट्रातील रहिवासी.','Aadhaar, school leaving certificate, father''s caste proof, ration card.','आधार, शाळा सोडल्याचा दाखला, वडिलांचा जातीचा पुरावा, रेशनकार्ड.','Required for reservation in education, jobs and welfare schemes.','शिक्षण, नोकरी व योजनांतील आरक्षणासाठी आवश्यक.','Certificate','प्रमाणपत्र','https://aaplesarkar.mahaonline.gov.in','1800-120-8040',17),
('Residence Certificate','रहिवासी प्रमाणपत्र','Certificate confirming your place of residence.','आपल्या राहत्या ठिकाणाची पुष्टी करणारे प्रमाणपत्र.','Any person residing at the given address in Maharashtra.','महाराष्ट्रातील दिलेल्या पत्त्यावर राहणारी कोणतीही व्यक्ती.','Aadhaar, ration card, electricity bill, self-declaration.','आधार, रेशनकार्ड, वीज बिल, स्वयंघोषणापत्र.','Used as address proof for admissions, jobs and government services.','प्रवेश, नोकरी व शासकीय सेवांसाठी पत्त्याचा पुरावा.','Certificate','प्रमाणपत्र','https://aaplesarkar.mahaonline.gov.in','1800-120-8040',18),
('Domicile Certificate','अधिवास प्रमाणपत्र','Certificate proving that you are a permanent resident of Maharashtra.','आपण महाराष्ट्राचे कायम रहिवासी असल्याचे सिद्ध करणारे प्रमाणपत्र.','Persons residing in Maharashtra for the period prescribed by the rules.','नियमानुसार विहित कालावधीपासून महाराष्ट्रात राहणाऱ्या व्यक्ती.','Aadhaar, school leaving certificate, ration card, residence proof.','आधार, शाळा सोडल्याचा दाखला, रेशनकार्ड, रहिवासी पुरावा.','Required for state quota admissions and state government jobs.','राज्य कोट्यातील प्रवेश व राज्य शासकीय नोकऱ्यांसाठी आवश्यक.','Certificate','प्रमाणपत्र','https://aaplesarkar.mahaonline.gov.in','1800-120-8040',19),
('Birth Certificate','जन्म दाखला','Official registration certificate of birth.','जन्माची अधिकृत नोंदणी करणारे प्रमाणपत्र.','Parents or guardians registering a birth, or citizens needing a copy.','जन्म नोंदणी करणारे पालक किंवा प्रत हवी असलेले नागरिक.','Hospital birth record, parents'' Aadhaar, address proof.','रुग्णालयाची जन्म नोंद, पालकांचे आधार, रहिवासी पुरावा.','Legal proof of date of birth for school, passport and all documents.','शाळा, पासपोर्ट व सर्व कागदपत्रांसाठी जन्मतारखेचा कायदेशीर पुरावा.','Certificate','प्रमाणपत्र','https://crsorgi.gov.in','1800-120-8040',20),
('Death Certificate','मृत्यू दाखला','Official registration certificate of death.','मृत्यूची अधिकृत नोंदणी करणारे प्रमाणपत्र.','Family members of the deceased person.','मृत व्यक्तीचे कुटुंबीय.','Hospital death record, Aadhaar of deceased, applicant''s ID proof.','रुग्णालयाची मृत्यू नोंद, मृताचे आधार, अर्जदाराचा ओळखपत्र पुरावा.','Needed for insurance claims, pension and property transfer.','विमा दावा, पेन्शन व मालमत्ता हस्तांतरणासाठी आवश्यक.','Certificate','प्रमाणपत्र','https://crsorgi.gov.in','1800-120-8040',21),
('Marriage Registration','विवाह नोंदणी','Legal registration of marriage with the local body.','स्थानिक स्वराज्य संस्थेकडे विवाहाची कायदेशीर नोंदणी.','Married couples residing in Maharashtra with valid marriage proof.','वैध विवाह पुरावा असलेली महाराष्ट्रातील विवाहित जोडपी.','Aadhaar of both spouses, marriage invitation or photos, witnesses'' ID.','दोघांचे आधार, विवाह पत्रिका किंवा फोटो, साक्षीदारांचे ओळखपत्र.','Legal marriage certificate for visa, bank and insurance purposes.','व्हिसा, बँक व विमा कामांसाठी कायदेशीर विवाह प्रमाणपत्र.','Certificate','प्रमाणपत्र','https://aaplesarkar.mahaonline.gov.in','1800-120-8040',22),
('PAN Card','पॅन कार्ड','Permanent Account Number card issued by the Income Tax Department.','आयकर विभागाकडून दिले जाणारे कायम खाते क्रमांक कार्ड.','Any Indian citizen or entity requiring a PAN for financial transactions.','आर्थिक व्यवहारांसाठी पॅन आवश्यक असलेला कोणताही भारतीय नागरिक.','Aadhaar, date of birth proof, address proof, photograph.','आधार, जन्मतारखेचा पुरावा, रहिवासी पुरावा, छायाचित्र.','Mandatory for bank accounts, income tax returns and large transactions.','बँक खाते, आयकर विवरण व मोठ्या व्यवहारांसाठी आवश्यक.','Document','कागदपत्र','https://www.onlineservices.nsdl.com','020-27218080',23),
('Passport','पासपोर्ट','Indian passport application and renewal through Passport Seva.','पासपोर्ट सेवा मार्फत भारतीय पासपोर्ट अर्ज व नूतनीकरण.','Indian citizens with valid identity and address proof.','वैध ओळख व रहिवासी पुरावा असलेले भारतीय नागरिक.','Aadhaar, birth certificate, address proof, old passport if any.','आधार, जन्म दाखला, रहिवासी पुरावा, जुना पासपोर्ट असल्यास.','Internationally accepted travel and identity document.','आंतरराष्ट्रीय प्रवास व ओळखीसाठी मान्य दस्तऐवज.','Document','कागदपत्र','https://www.passportindia.gov.in','1800-258-1800',24)
)
INSERT INTO public.schemes (name_en, name_mr, desc_en, desc_mr, eligibility_en, eligibility_mr, documents_en, documents_mr, benefits_en, benefits_mr, category_en, category_mr, website_url, helpline, sort_order, is_active)
SELECT d.name_en, d.name_mr, d.desc_en, d.desc_mr, d.elig_en, d.elig_mr, d.docs_en, d.docs_mr, d.ben_en, d.ben_mr, d.cat_en, d.cat_mr, d.url, d.helpline, d.ord, true
FROM d
WHERE NOT EXISTS (
  SELECT 1 FROM public.schemes s WHERE lower(s.name_en) = lower(d.name_en) OR lower(d.name_en) LIKE lower(s.name_en) || '%'
);